<template><view class="page"><view class="card"><view class="field"><text class="field-label">用户名</text><input v-model="form.username" class="input" /></view><view class="field"><text class="field-label">昵称</text><input v-model="form.nickname" class="input" /></view><view class="field"><text class="field-label">密码</text><input v-model="form.password" class="input" password /></view><view class="field"><text class="field-label">确认密码</text><input v-model="confirm" class="input" password /></view><button class="primary-btn" :loading="loading" @click="submit">完成注册</button></view></view></template>
<script setup lang="ts">import{reactive,ref}from'vue';import{api}from'@/services/api';const form=reactive({username:'',nickname:'',password:''}),confirm=ref(''),loading=ref(false);async function submit(){if(!/^[A-Za-z0-9_]{3,16}$/.test(form.username)||form.password.length<8||form.password!==confirm.value)return uni.showToast({title:'请检查用户名和密码',icon:'none'});loading.value=true;try{await api('/auth/register','POST',form);uni.showToast({title:'注册成功'});setTimeout(()=>uni.navigateBack(),600)}finally{loading.value=false}}</script>
